const {
  conversation_id,
  contact_name,
  contact_username,
  ultimo_mensaje_content,
  ultimo_mensaje_type,
  ultimo_mensaje_created_at,
  ultimo_mensaje_fecha,
  es_audio,
  es_imagen,
  labels
} = $input.item.json;

const tieneEtiqueta = Array.isArray(labels) && labels.includes('recordatorio_enviado');

// Si no hay contenido de mensaje, skip
if (!ultimo_mensaje_content) {
  return {
    json: {
      skip: true,
      reason: 'Sin mensajes válidos',
      conversation_id,
      contact_name,
      contact_username,
      horas_transcurridas: null,
      accion: 'ignorar'
    }
  };
}

// Si el último mensaje es entrante y es audio o imagen, ignorar
if (ultimo_mensaje_type === 0 && (es_audio || es_imagen)) {
  return {
    json: {
      skip: true,
      reason: es_audio ? 'Último mensaje es audio entrante' : 'Último mensaje es imagen entrante',
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: null,
      accion: 'ignorar'
    }
  };
}

// Si el último mensaje es entrante y tiene etiqueta → quitar etiqueta (respondió)
if (ultimo_mensaje_type === 0 && tieneEtiqueta) {
  return {
    json: {
      skip: false,
      reason: 'Cliente respondió, quitar etiqueta',
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: null,
      accion: 'quitar_etiqueta'
    }
  };
}

// Si el último mensaje es entrante sin etiqueta, ignorar
if (ultimo_mensaje_type === 0) {
  return {
    json: {
      skip: true,
      reason: 'Último mensaje es entrante',
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: null,
      accion: 'ignorar'
    }
  };
}

// Calcular horas transcurridas
const ahoraUnix = Math.floor(Date.now() / 1000);
const horasTranscurridas = (ahoraUnix - ultimo_mensaje_created_at) / 3600;

// Verificar mensaje de cierre
const MENSAJE_CIERRE = "Listo, tu empresa quedó registrada. En breve, un asesor de tu zona te contactará para darte el acceso formal. ¡Éxitos!";
const esMensajeCierre = ultimo_mensaje_content.trim() === MENSAJE_CIERRE.trim();

// Si es mensaje de cierre, cerrar
if (esMensajeCierre) {
  return {
    json: {
      skip: false,
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: Math.round(horasTranscurridas),
      es_mensaje_cierre: true,
      accion: 'cerrar'
    }
  };
}

// Si tiene etiqueta + último saliente + > 24h → cerrar
if (tieneEtiqueta && horasTranscurridas > 24) {
  return {
    json: {
      skip: false,
      reason: 'Con etiqueta y más de 24h sin respuesta',
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: Math.round(horasTranscurridas),
      es_mensaje_cierre: false,
      accion: 'cerrar'
    }
  };
}

// Si tiene etiqueta + último saliente + < 24h → ignorar (esperando respuesta)
if (tieneEtiqueta && horasTranscurridas <= 24) {
  return {
    json: {
      skip: true,
      reason: 'Ya tiene etiqueta, esperando respuesta',
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: Math.round(horasTranscurridas),
      accion: 'ignorar'
    }
  };
}

// Sin etiqueta + último saliente + > 24h → cerrar sin recordatorio
if (horasTranscurridas > 24) {
  return {
    json: {
      skip: false,
      reason: 'Más de 24h sin respuesta',
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: Math.round(horasTranscurridas),
      es_mensaje_cierre: false,
      accion: 'cerrar'
    }
  };
}

const MENSAJE_NO_MAYORISTA = "Entiendo. Somos mayoristas exclusivos y no manejamos ventas al detal, pero podemos referirte con un aliado en tu zona. ¿En qué Estado te encuentras?";
const esMensajeNoMayorista = ultimo_mensaje_content.trim() === MENSAJE_NO_MAYORISTA.trim();

if (esMensajeNoMayorista && horasTranscurridas > 24) {
  return {
    json: {
      skip: false,
      reason: 'No mayorista + más de 24h sin respuesta',
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: Math.round(horasTranscurridas),
      es_mensaje_cierre: false,
      accion: 'cerrar'
    }
  };
}

if (esMensajeNoMayorista && horasTranscurridas <= 24) {
  return {
    json: {
      skip: true,
      reason: 'No mayorista + menos de 24h, esperando respuesta',
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: Math.round(horasTranscurridas),
      accion: 'ignorar'
    }
  };
}

const MENSAJE_NO_CANAL = "Gracias por tu mensaje. Por este canal gestionamos exclusivamente la atención a nuestros aliados comerciales, así que no es el medio indicado para este tipo de propuestas.";
const esMensajeNoCanal = ultimo_mensaje_content.trim() === MENSAJE_NO_CANAL.trim();

if (esMensajeNoCanal) {
  return {
    json: {
      skip: true,
      reason: 'Mensaje de canal no indicado, ignorar siempre',
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: Math.round(horasTranscurridas),
      accion: 'ignorar'
    }
  };
}


// Sin etiqueta + último saliente + < 24h → enviar recordatorio
// Sin etiqueta + último saliente + < 24h
// Solo enviar recordatorio si han pasado al menos X horas
const HORAS_MINIMAS = 6; // ajusta este valor

if (horasTranscurridas < HORAS_MINIMAS) {
  return {
    json: {
      skip: true,
      reason: `Menos de ${HORAS_MINIMAS}h transcurridas`,
      conversation_id,
      contact_name,
      contact_username,
      ultimo_mensaje_content,
      ultimo_mensaje_type,
      ultimo_mensaje_fecha,
      horas_transcurridas: Math.round(horasTranscurridas),
      accion: 'ignorar'
    }
  };
}

return {
  json: {
    skip: false,
    conversation_id,
    contact_name,
    contact_username,
    ultimo_mensaje_content,
    ultimo_mensaje_type,
    ultimo_mensaje_fecha,
    horas_transcurridas: Math.round(horasTranscurridas),
    es_mensaje_cierre: false,
    accion: 'recordatorio'
  }
};

const raw = $input.item.json;
const messages = Array.isArray(raw.payload) ? raw.payload : [];

const conversationId =
  (messages.length > 0 ? messages[0].conversation_id : null) ||
  $('💾 Guardar Conv ID').item.json.conversation_id;

const contactName = 
  raw.meta?.contact?.name ||
  messages.find(m => m.message_type === 0)?.sender?.name ||
  'Desconocido';

const contactUsername =
  raw.meta?.contact?.additional_attributes?.social_instagram_user_name ||
  messages.find(m => m.message_type === 0)?.sender?.additional_attributes?.social_instagram_user_name ||
  null;

const labels = raw.meta?.labels || [];

// Incluir mensajes con texto, audio o imagen
const validMessages = messages.filter(m => {
  if (m.message_type === 2) return false;

  const tieneTexto = m.content && m.content.trim() !== '';
  const esAudio = m.attachments?.some(a => a.file_type === 'audio');
  const esImagen = m.attachments?.some(a => ['image', 'ig_post', 'ig_reel'].includes(a.file_type));

  return tieneTexto || esAudio || esImagen;
});

if (validMessages.length === 0) {
  return {
    json: {
      conversation_id: conversationId,
      contact_name: contactName,
      contact_username: contactUsername,
      ultimo_mensaje_content: null,
      ultimo_mensaje_type: null,
      ultimo_mensaje_created_at: null,
      ultimo_mensaje_fecha: null,
      es_audio: false,
      es_imagen: false,
      error: 'Sin mensajes válidos'
    }
  };
}

validMessages.sort((a, b) => b.created_at - a.created_at);
const ultimo = validMessages[0];

const esAudio = ultimo.attachments?.some(a => a.file_type === 'audio') ?? false;
const esImagen = ultimo.attachments?.some(a => ['image', 'ig_post', 'ig_reel'].includes(a.file_type)) ?? false;

let ultimoContenido = ultimo.content;
if (esAudio) ultimoContenido = '[audio]';
if (esImagen) ultimoContenido = '[imagen]';

const fecha = new Date(ultimo.created_at * 1000);
const ultimo_mensaje_fecha_legible = fecha.toLocaleString('es-VE', {
  timeZone: 'America/Caracas',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  hour12: true
});

return {
  json: {
    conversation_id: conversationId,
    contact_name: contactName,
    contact_username: contactUsername,
    labels: labels,
    ultimo_mensaje_content: ultimoContenido,
    ultimo_mensaje_type: ultimo.message_type,
    ultimo_mensaje_created_at: ultimo.created_at,
    ultimo_mensaje_fecha: ultimo_mensaje_fecha_legible,
    es_audio: esAudio,
    es_imagen: esImagen
  }
};
